<style>
:root{--ao-red:#611eb2;--ao-red-dark:#4d168f;--ao-red-soft:#f4edfc;--ao-black:#171021;--ao-ink:#101827;--ao-muted:#667085;--ao-bg:#f7f6f9;--ao-line:#e5e1ea;--ao-card:#fff}
.ao-training{font-family:"Roboto",Arial,sans-serif;background:var(--ao-bg);color:var(--ao-ink);min-height:70vh;padding:42px 0 70px}.ao-wrap{width:min(1180px,calc(100% - 32px));margin:auto}.ao-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:26px}.ao-toolbar-links{display:flex;gap:8px;flex-wrap:wrap}.ao-chip-link,.ao-icon-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px;padding:0 16px;border:1px solid var(--ao-line);border-radius:999px;background:#fff;color:var(--ao-ink);font-weight:800;text-decoration:none}.ao-chip-link:hover,.ao-icon-btn:hover{border-color:var(--ao-red);color:var(--ao-red)}.ao-chip-link.active{background:var(--ao-black);border-color:var(--ao-black);color:#fff}.ao-cart-badge{min-width:20px;height:20px;padding:0 5px;border-radius:999px;background:var(--ao-red);color:#fff;font-size:11px;display:inline-flex;align-items:center;justify-content:center}.ao-account{display:flex;align-items:center;gap:10px}.ao-avatar{width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:var(--ao-black);color:#fff;font-weight:900}.ao-panel{background:var(--ao-card);border:1px solid var(--ao-line);border-radius:22px;box-shadow:0 18px 50px rgba(44,22,68,.07)}.ao-btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:46px;padding:0 22px;border:1px solid transparent;border-radius:999px;font-weight:900;text-decoration:none;cursor:pointer;transition:.18s}.ao-btn-red{background:var(--ao-red);color:#fff;box-shadow:0 12px 24px rgba(97,30,178,.2)}.ao-btn-red:hover{background:var(--ao-red-dark);color:#fff;transform:translateY(-1px)}.ao-btn-dark{background:var(--ao-black);color:#fff}.ao-btn-outline{border-color:#352047;background:#fff;color:#171021}.ao-btn-outline:hover{border-color:var(--ao-red);color:var(--ao-red)}.ao-btn-sm{min-height:38px;padding:0 16px;font-size:13px}.ao-eyebrow{font-size:12px;letter-spacing:.18em;font-weight:900;text-transform:uppercase;color:var(--ao-red)}.ao-title{font-size:clamp(32px,4vw,58px);line-height:.96;font-weight:900;letter-spacing:-.04em;margin:8px 0 16px}.ao-section-title{font-size:30px;font-weight:900;letter-spacing:-.03em;margin:0}.ao-muted{color:var(--ao-muted)}.ao-alert{padding:14px 18px;border-radius:14px;margin-bottom:18px;font-weight:700}.ao-alert-success{background:#ecfdf3;border:1px solid #abefc6;color:#067647}.ao-alert-error{background:#fff1f3;border:1px solid #fda4af;color:#b42318}.ao-field label{display:block;font-size:12px;font-weight:900;letter-spacing:.05em;text-transform:uppercase;margin-bottom:7px}.ao-input,.ao-select,.ao-textarea{width:100%;border:1px solid #d9e0e8;border-radius:12px;background:#fff;min-height:46px;padding:10px 13px;color:var(--ao-ink);font-weight:700;outline:none}.ao-textarea{min-height:100px}.ao-input:focus,.ao-select:focus,.ao-textarea:focus{border-color:var(--ao-red);box-shadow:0 0 0 4px rgba(97,30,178,.09)}.ao-grid-2{display:grid;grid-template-columns:1fr 1fr;gap:22px}.ao-grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.ao-stat{padding:18px;border:1px solid var(--ao-line);border-radius:16px;background:#fff}.ao-stat span{display:block;color:var(--ao-muted);font-size:12px;font-weight:800;text-transform:uppercase}.ao-stat strong{font-size:26px}.ao-tag{display:inline-flex;align-items:center;gap:6px;min-height:28px;padding:0 10px;border-radius:999px;background:var(--ao-red-soft);color:var(--ao-red);font-size:12px;font-weight:900}.ao-session-card{border:1px solid var(--ao-line);border-radius:20px;background:#fff;padding:20px;display:flex;flex-direction:column;gap:14px}.ao-session-card h3{font-size:24px;font-weight:900;margin:0}.ao-session-meta{display:grid;gap:10px}.ao-meta-row{display:flex;gap:9px;align-items:flex-start;color:#475467;font-weight:700}.ao-meta-row i{color:var(--ao-red);width:18px;margin-top:3px}.ao-session-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:auto}.ao-calendar{overflow:hidden;border:1px solid var(--ao-line);border-radius:22px;background:#fff}.ao-calendar-head{display:grid;grid-template-columns:repeat(7,1fr);background:var(--ao-black);color:#fff}.ao-calendar-head div{padding:13px;text-align:center;font-size:11px;font-weight:900;letter-spacing:.1em}.ao-calendar-grid{display:grid;grid-template-columns:repeat(7,1fr)}.ao-day{min-height:118px;border-right:1px solid var(--ao-line);border-bottom:1px solid var(--ao-line);padding:10px;font-weight:800;position:relative}.ao-day:nth-child(7n){border-right:0}.ao-day.muted{background:#f8fafc;color:#98a2b3}.ao-day.today>span{display:inline-flex;width:28px;height:28px;border-radius:50%;align-items:center;justify-content:center;background:var(--ao-red);color:#fff}.ao-calendar-event{display:block;margin-top:8px;padding:7px;border:1px solid #d9c0f5;border-radius:9px;background:#faf7ff;color:#111;text-decoration:none;font-size:10px;line-height:1.25}.ao-calendar-event b{display:block}.ao-auth{width:min(980px,calc(100% - 32px));margin:0 auto;display:grid;grid-template-columns:1.1fr 1fr;overflow:hidden}.ao-auth-visual{min-height:540px;padding:40px;position:relative;display:flex;flex-direction:column;justify-content:flex-end;color:#fff;background:linear-gradient(0deg,rgba(23,16,33,.82),rgba(23,16,33,.18)),url('{{ asset('public/assets/images/hero-bg.jpg') }}') center/cover}.ao-auth-visual img{width:170px;position:absolute;top:28px;left:32px;filter:drop-shadow(0 5px 12px rgba(0,0,0,.35))}.ao-auth-form{padding:42px}.ao-auth-form h1{font-size:38px;font-weight:900;line-height:1;letter-spacing:-.035em}.ao-summary{position:sticky;top:126px;padding:24px}.ao-summary-row{display:flex;justify-content:space-between;gap:20px;padding:9px 0;font-weight:800;color:#475467}.ao-summary-total{border-top:1px solid var(--ao-line);margin-top:10px;padding-top:16px;display:flex;justify-content:space-between;align-items:center;font-size:20px;font-weight:900}.ao-summary-total strong{font-size:32px;color:var(--ao-red)}.ao-cart-item{padding:22px;border:1px solid var(--ao-line);border-radius:20px;background:#fff;margin-bottom:16px}.ao-cart-item-head{display:flex;justify-content:space-between;gap:20px}.ao-cart-session{margin-top:14px;padding:16px;border:1px solid #dcc8f2;border-radius:16px;background:#faf7ff}.ao-modal-card{border:0;border-radius:22px;overflow:hidden}.ao-modal-head{background:linear-gradient(90deg,var(--ao-black),#3a1d54);color:#fff;padding:18px 22px;display:flex;align-items:center;justify-content:space-between}.ao-player-option{display:block;border:1px solid var(--ao-line);border-radius:14px;padding:13px;margin-bottom:10px;cursor:pointer}.ao-player-option:has(input:checked){border-color:var(--ao-red);background:var(--ao-red-soft)}.ao-order-card{border:1px solid var(--ao-line);border-radius:16px;padding:16px;margin-top:12px}.ao-table{width:100%;border-collapse:collapse}.ao-table th,.ao-table td{padding:12px;border-bottom:1px solid var(--ao-line);text-align:left}.ao-status{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:11px;font-weight:900;background:#fff2cc;color:#8a5b00}.ao-status.booked,.ao-status.paid,.ao-status.completed{background:#dcfae6;color:#067647}.ao-status.cancelled{background:#fee4e2;color:#b42318}
@media(max-width:900px){.ao-grid-3,.ao-grid-2,.ao-auth{grid-template-columns:1fr}.ao-auth-visual{min-height:390px}.ao-summary{position:static}.ao-calendar{overflow-x:auto}.ao-calendar-head,.ao-calendar-grid{min-width:760px}.ao-toolbar{align-items:flex-start;flex-direction:column}.ao-session-actions{grid-template-columns:1fr}}
</style>
